    const message=status==="AVAILABLE"?"Horário disponível.":status==="CONFLICT_HARD_BLOCK"?
      `Não posso fazer encaixe nesse horário.${causes.includes("RESOURCE")?" A sala ou equipamento está reservado.":causes.includes("WAITLIST")?" O horário está reservado por uma oferta da fila.":causes.includes("SALON_CLOSED")?" O salão está fechado.":" Há uma restrição de agenda ou permissão."} ${options}`:
      missing[0]==="override_reason"?"Qual o motivo do encaixe?":missing.length?
        `${inspected.services.map(s=>s.name).join(", ")} vai até ${clock(endLocal)}${conflicts[0]?` e há outro atendimento às ${clock(conflicts[0].startLocal)}`:" e há conflito na agenda"}. Quer fazer o encaixe ou escolher outro horário?`:
        `Encaixe solicitado para ${clock(startLocal)}–${clock(endLocal)}, com motivo registrado. Aguarda confirmação.`;
