export function createServicesAgent(model: Model, receive: (patch: ServicePatch | CustomerInterpretation | SchedulingInterpretation | BatchInterpretation | FinancialInterpretation | InventoryInterpretation | CommunicationInterpretation | CapabilitySelection) => void, skill: SecretarySkill | "discovery" = "services", multiActionV2 = false) {
